package io.scenariomesh.core;import java.net.URI;import java.time.*;import java.util.*;public final class Domain{private Domain(){}public record ScenarioId(String value){public ScenarioId{Objects.requireNonNull(value);}}public record WorkerId(String value){public WorkerId{Objects.requireNonNull(value);}}public record RunId(String value){public RunId{Objects.requireNonNull(value);}public static RunId create(){return new RunId(UUID.randomUUID().toString());}}public enum WorkerStatus{STARTING,READY,BUSY,IDLE,DRAINING,STOPPING,STOPPED,UNHEALTHY,DEAD}public enum ResultStatus{PASSED,TEST_FAILURE,INFRASTRUCTURE_FAILURE,WORKER_FAILURE,DISCOVERY_FAILURE,CONFIGURATION_FAILURE}public record ScenarioTask(ScenarioId id,String displayName,String adapterId,String framework,URI source,Integer line,String selector,Set<String> tags,Map<String,String> metadata){public ScenarioTask{Objects.requireNonNull(id);Objects.requireNonNull(displayName);Objects.requireNonNull(adapterId);Objects.requireNonNull(framework);Objects.requireNonNull(selector);tags=Set.copyOf(tags==null?Set.of():tags);metadata=Map.copyOf(metadata==null?Map.of():metadata);}}public record ExecutionResult(ScenarioId scenarioId,String displayName,ResultStatus status,Duration duration,WorkerId workerId,int attempt,Instant startedAt,Instant finishedAt,String failureMessage,String failureType){public ExecutionResult{Objects.requireNonNull(scenarioId);Objects.requireNonNull(displayName);Objects.requireNonNull(status);Objects.requireNonNull(duration);Objects.requireNonNull(workerId);Objects.requireNonNull(startedAt);Objects.requireNonNull(finishedAt);}public boolean passed(){return status==ResultStatus.PASSED;}}}
